// NULL-tolerant scan buffer for apiKeyScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type apiKeyPreloadBuf struct {
	ID           null.Val[uuid.UUID]
	Name         null.Val[string]
	SecretHash   null.Val[[]byte]
	CreateTime   null.Val[time.Time]
	ExpireTime   null.Val[time.Time]
	RevokeTime   null.Val[time.Time]
	LastUsedTime null.Val[time.Time]
	UserID       null.Val[int64]
}

// apiKeyScanMapperNullable maps the preloaded apiKey
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func apiKeyScanMapperNullable(prefix string) scan.Mapper[*APIKey] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*APIKey, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *apiKeyPreloadBuf) any
		}
		targets := make([]target, 0, 8)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.ID }})
			case "name":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.Name }})
			case "secret_hash":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.SecretHash }})
			case "create_time":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.CreateTime }})
			case "expire_time":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.ExpireTime }})
			case "revoke_time":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.RevokeTime }})
			case "last_used_time":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.LastUsedTime }})
			case "user_id":
				targets = append(targets, target{i, func(b *apiKeyPreloadBuf) any { return &b.UserID }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(apiKeyPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*APIKey, error) {
				buf := link.(*apiKeyPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.SecretHash.IsValue()) &&
					!(buf.CreateTime.IsValue()) &&
					!(buf.ExpireTime.IsValue()) &&
					!(buf.RevokeTime.IsValue()) &&
					!(buf.LastUsedTime.IsValue()) &&
					!(buf.UserID.IsValue()) {
					return nil, nil
				}

				o := new(APIKey)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.SecretHash.IsValue() {
					o.SecretHash = buf.SecretHash.MustGet()
				}
				if buf.CreateTime.IsValue() {
					o.CreateTime = buf.CreateTime.MustGet()
				}
				o.ExpireTime = buf.ExpireTime
				o.RevokeTime = buf.RevokeTime
				o.LastUsedTime = buf.LastUsedTime
				if buf.UserID.IsValue() {
					o.UserID = buf.UserID.MustGet()
				}
				return o, nil
			}
	}
}

func (o *APIKey) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "APIKeyScopes":
		rels, ok := retrieved.(APIKeyScopeSlice)
		if !ok {
			return fmt.Errorf("apiKey cannot load %T as %q", retrieved, name)
		}

		o.R.APIKeyScopes = rels
		o.R.Loaded.APIKeyScopes = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.APIKey = o
				rel.R.Loaded.APIKey = true
			}
		}
		return nil
	case "User":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("apiKey cannot load %T as %q", retrieved, name)
		}

		o.R.User = rel
		o.R.Loaded.User = true

		if rel != nil {
			rel.R.APIKeys = APIKeySlice{o}
		}
		return nil
	default:
		return fmt.Errorf("apiKey has no relationship %q", name)
	}
}

