// LoadAPIKeyScopes loads the apiKey's APIKeyScopes into the .R struct
func (o *APIKey) LoadAPIKeyScopes(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.APIKeyScopes = nil
	o.R.Loaded.APIKeyScopes = false

	related, err := o.APIKeyScopes(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.APIKey = o
		rel.R.Loaded.APIKey = true
	}

	o.R.APIKeyScopes = related
	o.R.Loaded.APIKeyScopes = true
	return nil
}

// LoadAPIKeyScopes loads the apiKey's APIKeyScopes into the .R struct
func (os APIKeySlice) LoadAPIKeyScopes(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	apiKeyScopes, err := os.APIKeyScopes(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.APIKeyScopes = nil
		o.R.Loaded.APIKeyScopes = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	apiKeyByKey := make(map[uuid.UUID][]*APIKey, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		apiKeyByKey[o.ID] = append(apiKeyByKey[o.ID], o)
	}

	for _, rel := range apiKeyScopes {

		owners, ok := apiKeyByKey[rel.APIKeyID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.APIKey = o
			rel.R.Loaded.APIKey = true

			o.R.APIKeyScopes = append(o.R.APIKeyScopes, rel)

		}
	}

	return nil
}

// LoadUser loads the apiKey's User into the .R struct
func (o *APIKey) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.User = nil
	o.R.Loaded.User = false

	related, err := o.User(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.APIKeys = APIKeySlice{o}

	o.R.User = related
	o.R.Loaded.User = true
	return nil
}

// LoadUser loads the apiKey's User into the .R struct
func (os APIKeySlice) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.User(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.User = nil
		o.R.Loaded.User = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	apiKeyByKey := make(map[int64][]*APIKey, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		apiKeyByKey[o.UserID] = append(apiKeyByKey[o.UserID], o)
	}

	for _, rel := range users {

		owners, ok := apiKeyByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.User != nil {
				continue
			}

			rel.R.APIKeys = append(rel.R.APIKeys, o)

			o.R.User = rel

		}
	}

	return nil
}

